export function pdDate(s){if(!s)return null;let v=String(s).trim();if(/^\d{8}$/.test(v))v=v.slice(0,4)+'-'+v.slice(4,6)+'-'+v.slice(6);else if(/^\d{2}\/\d{2}\/\d{4}$/.test(v)){const [d,m,y]=v.split('/');v=y+'-'+m+'-'+d;}const n=Date.parse(v);return Number.isFinite(n)?new Date(n).toISOString():null;}
