async function pdResolve(env,entity){const n=pdNorm(entity);if(n.length<5)return null;const all=await pdAll(env,'SELECT * FROM prod_entities');let matches=all.filter(e=>JSON.parse(e.aliases).some(a=>a.length>=6&&(' '+n+' ').includes(' '+a+' ')));if(matches.length===1)return matches[0];if(matches.length>1)return null;const master=await pdFirst(env,"SELECT value FROM prod_settings WHERE key='sec_master'");if(!master)return null;matches=JSON.parse(master.value).filter(r=>{const a=pdNorm(r.title);return a.length>=10&&(' '+n+' ').includes(' '+a+' ')});if(matches.length!==1)return null;const r=matches[0],out={symbol:r.ticker,name:r.title,sector:'Da classificare',aliases:JSON.stringify([pdNorm(r.title)]),proof_url:'https://www.sec.gov/edgar/browse/?CIK='+r.cik_str};await pdRun(env,'INSERT OR IGNORE INTO prod_entities (symbol,name,sector,aliases,proof_url,created_at) VALUES (?,?,?,?,?,?)',out.symbol,out.name,out.sector,out.aliases,out.proof_url,pdNow());return out;}
