export async function pdResearchNames(env,research,predictions=[]){const names=new Map(predictions.map(p=>[p.symbol,p.company]));for(const e of await pdAll(env,'SELECT symbol,name FROM prod_entities'))names.set(e.symbol,e.name);return research.map(r=>({...r,company:pdCompanies[r.symbol]?.company||names.get(r.symbol)||r.symbol}));}
export function pdAllocationExplanation(p){const rule=p.allocation_rules||{},amount=p.amount,n=p.positions.length,invested=p.positions.reduce((v,x)=>v+x.allocated,0),sectors={};for(const h of p.positions)sectors[h.sector||'Da classificare']=(sectors[h.sector||'Da classificare']||0)+h.allocated;return {positions:n,profile:p.risk,invested_pct:amount?100*invested/amount:0,cash_pct:amount?100*p.cash/amount:0,target_exposure_pct:rule.exposure==null?null:100*rule.exposure,max_name_pct:rule.maxName==null?null:100*rule.maxName,max_sector_pct:rule.maxSector==null?null:100*rule.maxSector,minimum_cash_pct:rule.exposure==null?null:100*(1-rule.exposure),capacity_from_names_pct:rule.maxName==null?null:100*Math.min(rule.exposure,n*rule.maxName),eligible_at_creation:p.selection_diagnostics?.eligible_count??null,screened_at_creation:p.selection_diagnostics?.screened_count??null,sector_allocations:Object.entries(sectors).map(([sector,value])=>({sector,pct:100*value/amount})),note:'Il profilo stabilisce limiti massimi, non impone di investire tutto. Il numero di posizioni dipende da segnali idonei, prezzi disponibili, ranking e vincoli. Le simulazioni esistenti conservano regole e pesi originali; i conteggi di selezione storici non registrati restano non disponibili.'};}
export function pdPortfolioView(p,admin,adminView=false){const out={...p,allocation_explanation:pdAllocationExplanation(p)};if(admin||adminView)return out;out.selection='Motivazioni disponibili nel dettaglio del titolo nell’Osservatorio.';out.positions=p.positions.map(({score,selection_snapshot,...h})=>h);return out;}

export function pdPatentLinks(number){const n=String(number||'').toUpperCase().replace(/[\s.\/-]/g,'');if(!/^[A-Z]{2}\d{5,14}(?:[A-Z]\d{0,2})?$/.test(n))return [];return [{name:'Espacenet',url:'https://worldwide.espacenet.com/patent/search?q='+encodeURIComponent('pn='+n)},{name:'Google Patents',url:'https://patents.google.com/patent/'+n+'/en'}];}

export async function pdDiscoveries(env){const rows=await pdAll(env,"SELECT id,source_id,published_at,first_seen,symbol,status,payload FROM prod_events WHERE source_id IN ('epo','epo-us','europepmc','federal','openalex','sec-filings') ORDER BY first_seen DESC LIMIT 40");return rows.map(r=>{const e=JSON.parse(r.payload);return {id:r.id,source:r.source_id,published_at:r.published_at,first_seen:r.first_seen,symbol:r.symbol,status:r.status,title:e.title,url:e.url,kind:e.kind,primary:e.primary,description:e.description,facts:e.facts,view_links:pdPatentLinks(e.facts?.publication_number),verification:e.verification}})}
